contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint p) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(p >= 0);
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint contractBalanceBefore = address(c).balance;
        uint callerBalanceBefore = address(this).balance;

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint contractBalanceAfter = address(c).balance;
        uint callerBalanceAfter = address(this).balance;

        assert(
            (reverted &&
                ownerAfter == ownerBefore &&
                depositsAfter == depositsBefore &&
                contractBalanceAfter == contractBalanceBefore &&
                callerBalanceAfter == callerBalanceBefore) ||
            (!reverted &&
                ownerAfter == ownerBefore &&
                depositsAfter == depositsBefore &&
                contractBalanceAfter == 0 &&
                callerBalanceAfter == callerBalanceBefore + contractBalanceBefore)
        );
    }

    receive() external payable {}
}

