    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 p) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(p >= 0);
        address ownerBefore;
        try c.owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        uint256 depositsBefore;
        try c.depositsCount() returns (uint256 __r) { depositsBefore = __r; } catch { return; }
        uint contractBalanceBefore = address(c).balance;
        uint callerBalanceBefore = address(this).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        address ownerAfter;
        try c.owner() returns (address __r) { ownerAfter = __r; } catch { return; }
        uint256 depositsAfter;
        try c.depositsCount() returns (uint256 __r) { depositsAfter = __r; } catch { return; }
        uint contractBalanceAfter = address(c).balance;
        uint callerBalanceAfter = address(this).balance;
        assertTrue((reverted &&
                ownerAfter == ownerBefore &&
                depositsAfter == depositsBefore &&
                contractBalanceAfter == contractBalanceBefore &&
                callerBalanceAfter == callerBalanceBefore) ||
            (!reverted &&
                ownerAfter == ownerBefore &&
                depositsAfter == depositsBefore &&
                contractBalanceAfter == 0 &&
                callerBalanceAfter == callerBalanceBefore + contractBalanceBefore));
    }

    function testFuzz_run(uint256 p) public {
        _run(p);
    }

    receive() external payable {}
